mapper.select:
SELECT fa.id as id, fa.file_id as fileId, fa.ref_type as refType, fa.ref_id as refId, fa.attached_at as attachedAt, fa.is_deleted as isDeleted, f.name as storedFileName, f.org_name as originalFileName, -- 파일 크기는 별도 테이블 컬럼 추가 필요 (임시로 빈 값) '' as fileSize, -- 확장자 추출 SUBSTRING_INDEX(f.org_name, '.', -1) as fileExtension, f.created_at as createdAt FROM file_attachments fa INNER JOIN file f ON fa.file_id = f.id WHERE 1=1
AND fa.ref_type = #{refType}
AND fa.ref_id = #{refId}
AND fa.is_deleted = #{isDeleted}
ORDER BY fa.attached_at DESC

mapper.update:
UPDATE file_attachments
SET 
    ref_type = #{newRefType},
    ref_id = #{newRefId}
WHERE ref_type = #{oldRefType}
AND ref_id = #{oldRefId}
AND is_deleted = 0
